import{z as D,x as o,o as e,c as i,q as s,j as r,D as B,d as A,s as n,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"HBM 与 3D 堆叠","description":"","frontmatter":{"title":"HBM 与 3D 堆叠","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hbm-3d-stack.md","filePath":"cs/hbm-3d-stack.md","lastUpdated":1791063341000}'),d={name:"cs/hbm-3d-stack.md"};function p(M,a,m,h,c,T){const t=o("Mermaid");return e(),i("div",null,[a[2]||(a[2]=s('<h1 id="hbm-与-3d-堆叠" tabindex="-1">HBM 与 3D 堆叠 <a class="header-anchor" href="#hbm-与-3d-堆叠" aria-label="Permalink to &quot;HBM 与 3D 堆叠&quot;">​</a></h1><div class="epigraph"><p>把 DRAM 晶片叠在逻辑基片上，用硅通孔做很宽很短的通道：带宽上来，容量与热仍受堆叠层数限制。</p><footer>—— 据 JEDEC HBM 标准；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/fr-fcfs">上一课</a>的调度在离芯片 DIMM 通道上跑，引脚数限制宽度。缺口是 <strong>HBM</strong>：3D 堆叠 DRAM + 宽 I/O，组织仍是通道/伪通道/bank/行，物理从 PCB 金手指换成中介层与 TSV。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DDR DIMM：板级走线、几十比特宽、GHz 级。HBM：每堆叠多个伪通道，数据宽度一个数量级以上，时钟可以更保守，靠并行取带宽。缺口不是新的行缓冲定义，而是<strong>封装层次</strong>改变通道数量与功耗分布：PHY 在中介层旁，控制器仍做 ACT/RD 与刷新。</p><p>3D 堆叠：TSV 连多层 DRAM 晶片。热从逻辑芯片和 DRAM 自刷新一起来，功耗墙在垂直方向更紧。</p><p><span class="marginnote">术语翻译：TSV（硅通孔）就是「在硅片上打竖井」的手段——让信号从上面一层的 DRAM 晶片垂直穿到下一层，而不是绕到芯片边缘的焊线。井又多又短，才凑得出上千根数据线并排工作。</span></p><h3 id="hbm-不是「把-cache-做进-dram-工艺」" tabindex="-1">HBM 不是「把 cache 做进 DRAM 工艺」 <a class="header-anchor" href="#hbm-不是「把-cache-做进-dram-工艺」" aria-label="Permalink to &quot;HBM 不是「把 cache 做进 DRAM 工艺」&quot;">​</a></h3><p>HBM 仍是 DRAM 电容，要刷新、有行缓冲。逻辑基片可以含控制器，不把 HBM 变成 SRAM 缓存。把 HBM 当片上 SRAM，一致性与保留时间会说错。也不等于 NAND 闪存堆叠（后课）。</p><p><span class="marginnote">JEDEC HBM/HBM2/HBM3 规范定义接口。CA:AQA 用 3D 与宽 I/O 讲带宽。本课不写 TSV 光刻工艺，不把 GPU 型号当标准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>地址映射切到更多伪通道。调度器实例变多，每伪通道仍可 FR-FCFS。容量：层数 × 密度，不及多 DIMM 服务器容量时用 DDR 做远端、HBM 做近端（异构内存），OS 可见性后课 NVM 再对照。</p>',12)),(e(),r(l,null,{default:B(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOGIC%5B%22%E9%80%BB%E8%BE%91%E8%8A%AF%E7%89%87%20%2F%20%E5%9F%BA%E7%89%87%22%5D%20--%3E%20INTP%5B%22%E4%B8%AD%E4%BB%8B%E5%B1%82%22%5D%0A%20%20INTP%20--%3E%20STK%5B%22DRAM%20%E6%99%B6%E7%89%87%E5%A0%86%E5%8F%A0%20TSV%22%5D%0A%20%20STK%20--%3E%20PC%5B%22%E4%BC%AA%E9%80%9A%E9%81%93%20%2B%20%E8%A1%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20PC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9D%9E%E6%98%93%E5%A4%B1%E4%B8%8E%E5%8F%A6%E4%B8%80%E5%A5%97%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"训练与校准仍在，只是通道极多，PHY 数字控制更重。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：带宽 ≈ 位宽 × 频率。一条 DDR5-6400 是 64 bit × 6.4 GT/s ≈ 51 GB/s；一个 HBM2 堆叠是 1024 bit × 2.4 GT/s ≈ 307 GB/s。后者时钟反而更低，靠 16 倍位宽取胜——「宽而短」的算术就这一行乘法。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"软错误：堆叠与 TSV 不取消 ECC。老化：热点在中心层。经济学：中介层与堆叠良率提高 NRE，故出现在带宽关键的加速器，而不是每块 PC 主板。后课闪存是另一介质，不要把「堆叠」三字共用成同一课。",-1)),a[7]||(a[7]=E("p",null,"同样量级的带宽，DDR 与 HBM 分别从哪里来：",-1)),(e(),r(l,null,{default:B(()=>[n(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20BW%5B%22%E7%9B%AE%E6%A0%87%3A%20%E6%8B%89%E9%AB%98%E5%B8%A6%E5%AE%BD%22%5D%20--%3E%20DDR%5B%22DDR%3A%2064%20bit%20%E7%AA%84%E9%80%9A%E9%81%93%22%5D%0A%20%20DDR%20--%3E%20F1%5B%22%E5%8F%AA%E8%83%BD%E6%8A%AC%E6%97%B6%E9%92%9F%E5%88%B0%20GHz%20%E7%BA%A7%22%5D%0A%20%20F1%20--%3E%20C1%5B%22%E6%9D%BF%E7%BA%A7%E9%95%BF%E8%B5%B0%E7%BA%BF%3A%20%E8%AE%AD%E7%BB%83%E9%9A%BE%2C%20%E5%8A%9F%E8%80%97%E9%AB%98%22%5D%0A%20%20BW%20--%3E%20HBM%5B%22HBM%3A%201024%20bit%20%E5%AE%BD%E6%8E%A5%E5%8F%A3%22%5D%0A%20%20HBM%20--%3E%20F2%5B%22%E6%97%B6%E9%92%9F%E4%BF%9D%E5%AE%88%E4%B9%9F%E8%83%BD%E8%BE%BE%E6%A0%87%22%5D%0A%20%20F2%20--%3E%20C2%5B%22%E4%B8%AD%E4%BB%8B%E5%B1%82%E7%9F%AD%E8%B5%B0%E7%BA%BF%3A%20%E5%B9%B6%E8%A1%8C%E6%8D%A2%E5%B8%A6%E5%AE%BD%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">常见误区：初学者容易以为堆叠层数越多越好。实际上 DRAM 刷新自发热叠上逻辑芯片的热，越靠中间层越难散，热点常在堆叠中部；层数是被热设计与良率（一片坏则整堆报废）压住的，不是想叠几层就几层。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲混合键合的全部工艺选项，不进入光刻套准。不把 HBM 带宽写成大模型必修——系统栏只给接口。不讨论显卡零售。</p><p>后课默认：HBM 是宽而短的 DRAM 通道加 3D 堆叠；命令语义仍是 DRAM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宽伪通道 + TSV 堆叠拉带宽；仍是 DRAM 行缓冲与刷新。</li><li>热与良率限制层数与谁用得起。</li><li>下一课介质换成非易失。</li><li>出处：JEDEC HBM；Hennessy and Patterson, CA:AQA。</li></ul>',6))])}const H=D(d,[["render",p]]);export{C as __pageData,H as default};
